{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C04", "C14", "C15", "C19", "C23", "C25", "C28", "C29", "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C38", "C39"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C14", "C25", "C28", "C31", "C38", "C33"],
  "claims": [
    {
      "claim": "The query is a pyrido[2,3-d]pyrimidinone 2-anilino CDK4/6 inhibitor scaffold. The supplied 2-anilinopyrimidine comparator context reports absolute oral bioavailability of 46% (C14), with additional fed/fasted records for the same scaffold context reporting 77% and 57% (C04, C15), all above the 20% threshold.",
      "card_ids": ["C04", "C14", "C15"]
    },
    {
      "claim": "The piperazine-containing heteroaromatic TDP223206 showed rat absolute bioavailability of 24.46% at 50 mg/kg (C25) and 32.95% at 10 mg/kg (C28), both above threshold, supporting that this chemotype can exceed 20% despite basic amine and high TPSA liabilities.",
      "card_ids": ["C25", "C28"]
    },
    {
      "claim": "New L3 oral exposure records for the close analog SHR6390 show measurable systemic exposure after a 150 mg oral dose: geometric-mean Cmax 52.2 ng/mL fasted (C38) and 81.8 ng/mL fed (C33), with monotherapy AUC0-inf 2140 h·ng/mL (C30); ribociclib, another CDK4/6 inhibitor of the same class, shows substantial steady-state Cmax/Ctrough (C32, C34, C36, C39). These records support oral absorption but do not directly quantify absolute F.",
      "card_ids": ["C29", "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C38", "C39"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20% for the query or close analogs; the ciprofloxacin interaction records (C37, C40) are not applicable to this molecule, and the low-bioavailability contexts present (paliperidone ER 28%, tacrolimus ~20-25%) are at or above threshold and structurally unrelated.",
      "card_ids": ["C03", "C07", "C16", "C37", "C40"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C29", "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C38", "C39"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the supplied cards.",
    "No query-specific IV/oral AUC comparison is available; the L3 AUC/Cmax records lack an IV comparator and therefore cannot directly establish the F >= 20% threshold.",
    "The SHR6390 records (M02) are for a close analog differing in the solubilizing substituent (piperidin-4-yl vs piperazin-1-yl), limiting exact transfer.",
    "The TDP223206 rat data (C25, C28) are from a different species and molecule.",
    "Ciprofloxacin interaction records (C37, C40) are not applicable to the query chemotype."
  ],
  "decision_summary": "Predicted high: F >= 20% is better supported. The unfavorable physicochemical prior is outweighed by direct absolute-F values above threshold for the 2-anilinopyrimidine comparator (46-77%) and by rat absolute F >20% for a piperazine-containing analog; new L3 oral exposure records for the close analog SHR6390 and same-class ribociclib confirm measurable oral absorption. No affirmative evidence supports F < 20%."
}

